"use strict";
import { useQuery } from "@tanstack/react-query";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const CHAIN_ID_TO_DEXSCREENER = {
  [UniverseChainId.Mainnet]: "abstract",
  [UniverseChainId.AbstractTestnet]: "abstract"
  // DexScreener may not have testnet data
};
async function fetchDexScreenerData(chainId, tokenAddress) {
  const dexScreenerChainId = CHAIN_ID_TO_DEXSCREENER[chainId];
  if (!dexScreenerChainId) {
    throw new Error(`Chain ID ${chainId} not supported by DexScreener`);
  }
  const url = `https://api.dexscreener.com/tokens/v1/${dexScreenerChainId}/${tokenAddress}`;
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`DexScreener API error: ${response.status} ${response.statusText}`);
  }
  const data = await response.json();
  if (!data || data.length === 0) {
    return {
      tvl: void 0,
      marketCap: void 0,
      fdv: void 0,
      volume24h: void 0,
      priceUsd: void 0,
      liquidity: void 0
    };
  }
  const mainPair = data[0];
  const normalizedAddress = tokenAddress.toLowerCase();
  const isBaseToken = mainPair.baseToken.address.toLowerCase() === normalizedAddress;
  let priceUsd;
  if (isBaseToken) {
    priceUsd = mainPair.priceUsd;
  } else {
    const basePrice = parseFloat(mainPair.priceUsd);
    const priceNative = parseFloat(mainPair.priceNative);
    if (priceNative > 0) {
      priceUsd = (basePrice / priceNative).toString();
    } else {
      priceUsd = "0";
    }
  }
  return {
    tvl: mainPair.liquidity?.usd,
    // TVL = liquidity in USD
    marketCap: mainPair.marketCap,
    fdv: mainPair.fdv,
    volume24h: mainPair.volume?.h24,
    priceUsd,
    liquidity: mainPair.liquidity?.usd
  };
}
export function useDexScreenerTokenData(chainId, tokenAddress) {
  return useQuery({
    queryKey: ["dexscreener", chainId, tokenAddress],
    queryFn: () => {
      if (!tokenAddress) {
        throw new Error("Token address is required");
      }
      return fetchDexScreenerData(chainId, tokenAddress);
    },
    enabled: !!tokenAddress && !!CHAIN_ID_TO_DEXSCREENER[chainId],
    staleTime: 3e4,
    // 30 seconds
    gcTime: 3e5,
    // 5 minutes
    retry: 2
  });
}
